`, "utf8"); writeFileSync(`${cwd}/journal.2.jsonl`, `${JSON.stringify({ n: 2, tags: [] })}
`, "utf8"); writeFileSync(`${cwd}/journal.1.jsonl`, `${JSON.stringify({ n: 1, tags: [] })}
`, "utf8"); forceRotation(file, [7]); const rows = readJsonl<{ text?: string }>(file); assert.ok( rows.some((row) => row.text === "durable lesson"), "SPEC §2: a lesson is carried into the fresh live journal instead of being deleted", ); // A carried lesson is not duplicated by the next rotation. forceRotation(file, [8]); const copies = readJsonl<{ text?: string }>(file).filter((row) => row.text === "durable lesson"); assert.equal(copies.length, 1, "carrying is once per dropped segment, not per rotation"); // Only the journal is pinned: events rotation still drops the oldest rows. const events = join(cwd, "events.jsonl"); writeFileSync(`${cwd}/events.3.jsonl`, `${JSON.stringify({ text: "old event", tags: ["lesson"] })}
`, "utf8"); forceRotation(events, [9]); assert.ok( !readJsonl<{ text?: string }>(events).some((row) => row.text === "old event"), "pinning applies to the journal, not to every ledger", ); }); }); EOF node --experimental-strip-types --test extension/test/ledger.test.ts 2>&1 | grep -E "^(ℹ (tests|pass|fail)|✖)" | head

